//! Tier D (docs/BOUNDARIES-COVERAGE.md): Loading and Errored boundaries
//! (`createLoadingBoundary`, `createErrorBoundary`: first loads and the
//! reveal, a refetch that keeps the content, an error caught and recovered,
//! `reset`, nesting, a boundary dying with its owner or re-created by its
//! owner's pass, a user effect held behind the fallback until the reveal),
//! tracked `isPending`/`latest` windows in memos and effects, and
//! `affects()` marks.
//!
//! The op programs and their traces are in fixtures/boundaries-units.json;
//! the traces are Solid's (rc.21, prod), regenerated by
//! docs/boundaries-fuzz/tools/unit-expectations.mjs from
//! docs/boundaries-fuzz/tools/unit-programs.json. Ten are hand-written; three
//! are `--boundaries` fuzz seeds that found a root cause (652, 957: a first
//! effect run's lane; 2171: the host's microtask turns).
use rust_solid::slice1::{Out, Runtime, Value};
use serde_json::Value as J;
use std::{
    io::Write,
    process::{Command, Stdio},
    rc::Rc,
};

fn driver(ops: &J) -> J {
    let mut child = Command::new(env!("CARGO_BIN_EXE_slice1-driver"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    writeln!(child.stdin.take().unwrap(), "{ops}").unwrap();
    let out = child.wait_with_output().unwrap();
    serde_json::from_slice(&out.stdout).unwrap()
}

fn unit(name: &str) {
    let all: J = serde_json::from_str(include_str!("fixtures/boundaries-units.json")).unwrap();
    let case = &all[name];
    assert!(case.is_object(), "{name} is a unit program");
    assert_eq!(driver(&case["ops"]), case["expected"], "{name}");
}

