/// The API directly: a Loading boundary over a host flight shows its
/// fallback, then its content when the flight lands; before the first value
/// the memo is loading (a read throws, `isPending` is false), and `affects`
/// makes it pending until the ambient mark is released at the next seam
/// (Solid's doc comments of `isPending` and `affects`; verdict.ts, affects.ts).
#[test]
fn loading_and_affects_on_the_api() {
    let mut rt = Runtime::default();
    let root = rt.create_root();
    let (a, output) = rt.with_owner(Some(root), |rt| {
        let a = rt.memo_async(
            Rc::new(|_: &mut Runtime, _| Ok(Out::Flight("q".into()))),
            None,
        );
        let content: rust_solid::slice1::Getter = Rc::new(move |rt: &mut Runtime| rt.read_value(a));
        let fallback: rust_solid::slice1::Getter = Rc::new(|_: &mut Runtime| Ok(Value::Int(-1)));
        let output = rt.loading_boundary(content, fallback);
        (a, output)
    });
    rt.run_microtasks(&mut |_, _| {});
    rt.flush();
    assert_eq!(rt.read_value(output).unwrap(), Value::Int(-1));
    // Loading, not pending: the untracked probe swallows the NotReadyError.
    assert!(rt.read_value(a).is_err());
    assert!(!rt.is_pending(a).unwrap());
    rt.settle_flight_value("q", Ok(Value::Int(7)));
    rt.run_microtasks(&mut |_, _| {});
    rt.flush();
    assert_eq!(rt.read_value(output).unwrap(), Value::Int(7));
    assert!(!rt.is_pending(a).unwrap());
    rt.affects(a);
    assert!(rt.is_pending(a).unwrap(), "a mark reads pending");
    rt.run_microtasks(&mut |_, _| {});
    rt.flush();
    assert!(
        !rt.is_pending(a).unwrap(),
        "the ambient mark is released at the seam"
    );
}
